import {setupScanner} from './scanner.js';
import {targetStatus,targetsForDay,adherenceDays,TARGET_KEYS} from './nutrition-status.js';
import {SPORT_OPTIONS,estimateExercise,exerciseSummary} from './exercise.js';
let adherenceRange=7,activityOpen=false;
import {WeightChart} from './weight-chart.js';
const weightChart=new WeightChart();
import {parseRenphoCSV,mergeRenpho,dailyWeights} from './renpho.js';
import {makeMealPreset,presetSelection,presetTotals} from './presets.js';
import {frequentFoods,foodKey} from './suggestions.js';
import {PlannerUI,withAmount,shiftDate} from './planner.js';
import {RecipeUI,recipeFood,recipeFoods} from './recipes.js';
import {parseFatSecretCSV,mergeFatSecret} from './fatsecret.js';
import {fixedProfile,mergeProfile} from './profile.js';
import {cloudConfig} from './cloud-config.js';
import {CloudStore} from './cloud.js';
const cloud=new CloudStore(cloudConfig);
let connected=false,syncError=false,lastCloudError='',sessionNotice='',busy=false;
import {predictTargets,predictorMarkup,bindTargetEditor,targetEditorFields,weightTimelineMarkup} from './predictor.js';
import {foods,totals,validBackup,entryNutrients} from './data.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const initial=()=>({version:1,profile:{name:'',goal:2000,protein:120,carbs:250,fat:65},entries:[],weights:[],activities:[],custom:[],recipes:[],plans:[],presets:[],dayReviews:[]});
let state=initial();if(!cloud.configured)try{const raw=localStorage.getItem('mi-nutricion');if(raw){const parsed=JSON.parse(raw);if(validBackup(parsed))state=parsed;else alert('Los datos guardados no son compatibles. Conserva una copia antes de importar otros datos.');}}catch{alert('No se pudo leer el almacenamiento local. Comprueba que tu navegador permite guardar datos.');}
let date=today(),meal='Desayuno',foodDestination='diary',planDate=null,foodSelection=[],dialogFoodList=null,results=[],page='hoy';
const pages={hoy:['◉','Diario'],alimentacion:['▤','Alimentación'],recetas:['▧','Recetas'],calendario:['▦','Calendario'],evolucion:['↗','Evolución'],actividad:['♧','Actividad'],perfil:['⚙','Mi perfil']};
const recipeUI=new RecipeUI({
 getRecipes:()=>state.recipes||[],
 chooseIngredient:()=>openFood('Desayuno','recipe'),
 saveRecipe:async recipe=>{state.recipes=[...(state.recipes||[]).filter(r=>r.id!==recipe.id),recipe];return save();},
 deleteRecipe:async id=>{state.recipes=(state.recipes||[]).filter(r=>r.id!==id);return save();},
 recordRecipe:(recipe,mode)=>{openFood();showResults([recipeFood(recipe,mode)]);}
});
const plannerUI=new PlannerUI({
 getActivityPresets:()=>state.activityPresets||[],getPlans:()=>state.plans||[],getEntries:()=>state.entries,getProfile:()=>state.profile,getActivities:()=>state.activities,
 addActivity:async activity=>{state.activities.push({...activity,id:crypto.randomUUID(),planned:true});return save();},
 removeActivity:async id=>{state.activities=state.activities.filter(a=>a.id!==id);return save();},
 completeActivity:async id=>{state.activities=state.activities.map(a=>a.id===id?{...a,planned:false}:a);return save();},
 navigate:day=>{date=day;$('#date').value=date;render();},
 chooseFood:(day,m)=>{planDate=day;openFood(m,'plan');},
 remove:async id=>{state.plans=(state.plans||[]).filter(p=>p.id!==id);return save();},
 changeAmount:async(id,amount)=>{state.plans=(state.plans||[]).map(p=>p.id===id?withAmount(p,amount):p);return save();},
 copy:async additions=>{state.plans=[...(state.plans||[]),...additions];return save();}
});
function selectDate(day){date=day;$('#date').value=date;render();}
$('#date').value=date;$('#date').onchange=e=>selectDate(e.target.value||today());
$('#previous-day').onclick=()=>selectDate(shiftDate(date,-1));
$('#next-day').onclick=()=>selectDate(shiftDate(date,1));
$('#today-button').onclick=()=>selectDate(today());
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
async function save(){
 if(!cloud.configured){try{localStorage.setItem('mi-nutricion',JSON.stringify(state));return true;}catch{toast('No se pudo guardar. Exporta una copia de seguridad.');return false;}}
 busy=true;document.querySelector('.app').inert=true;$('#food-dialog').inert=true;
 try{if(!connected)throw Error('Inicia sesión.');await cloud.save(structuredClone(state));syncError=false;return true;}
 catch(error){syncError=true;lastCloudError=error.message;$('#food-dialog').close();render();toast(error.message);return false;}
 finally{busy=false;document.querySelector('.app').inert=false;$('#food-dialog').inert=false;}
}
function downloadState(data=state){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`mi-nutricion-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function loadCloud(){const data=await cloud.load();if(data&&!validBackup(data))throw Error('Los datos remotos no son compatibles.');state=data||initial();recipeUI.reset();connected=true;syncError=false;render();}
function renderGate(){
 if(!cloud.configured)return false;
 if(connected&&!syncError)return false;
 $('#title').textContent='Mi perfil';
 $('#content').innerHTML='<div class="card"><h2>Perfil</h2><p>Acceso a los registros y a la configuración de la cuenta.</p></div>'+ (syncError?`<section class="card" id="account-panel"><h2>Guardado sin confirmar</h2><p>No cierres esta pestaña sin exportar los cambios pendientes. No se ha guardado una copia en el navegador. Si hay cambios de otro dispositivo debes recargar antes de editar.</p><button id="pending-export">Exportar cambios pendientes</button> <button id="cloud-reload">Recargar desde la base de datos</button><p id="cloud-error" role="alert"></p></section>`:`<section class="card" id="account-panel"><h2>Acceso a la cuenta</h2><p>Los registros se guardan en una base de datos privada. Solo tu cuenta autorizada tiene acceso. Por privacidad, la sesión termina al recargar o cerrar la pestaña.</p><form id="login-form" class="fields"><label>Email<input type="email" name="email" required autocomplete="username"></label><label>Contraseña<input type="password" name="password" required autocomplete="current-password"></label><button class="primary">Entrar</button></form><p id="cloud-error" role="alert"></p><button id="legacy-export">Exportar datos locales antiguos</button><p id="account-status" role="status"></p></section>`);
 if($('#account-status'))$('#account-status').textContent=sessionNotice;
 if(syncError){$('#cloud-error').textContent=lastCloudError;$('#pending-export').onclick=()=>downloadState();$('#cloud-reload').onclick=async()=>{if(!confirm('Se descartarán los cambios pendientes. ¿Has exportado una copia?'))return;try{await loadCloud();}catch(e){$('#cloud-error').textContent=e.message;}};}
 else{$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const v=formValues(e.target);try{await cloud.login(v.email,v.password);e.target.reset();sessionNotice='Sesión iniciada.';await loadCloud();}catch(error){$('#cloud-error').textContent=error.message;}finally{button.disabled=false;}};$('#legacy-export').onclick=()=>{try{const data=JSON.parse(localStorage.getItem('mi-nutricion'));if(!validBackup(data))throw Error();downloadState(data);}catch{toast('No se encontraron datos antiguos válidos.');}};}
 return true;
}
function navIcon(page){const paths={hoy:'<path d="M4 4h16v17H4zM8 2v4M16 2v4M8 10h8M8 14h8M8 18h5"/>',alimentacion:'<path d="M5 3v6a3 3 0 0 0 6 0V3M8 3v18M19 21V3c-4 3-4 10 0 10"/>',recetas:'<path d="M5 3h14v18H5a2 2 0 0 1 0-4h14M5 3v14M9 7h6M9 11h6"/>',calendario:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18M7 15h2M15 15h2M7 18h2"/>',evolucion:'<path d="M3 3v18h18M6 15l5-5 4 3 6-8"/>',actividad:'<circle cx="15" cy="4" r="2"/><path d="M12 8l-4 4-4 1M12 8l5 4h4M12 8l-1 7 5 3v4M11 15l-5 7"/>',perfil:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'};return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[page]}</svg>`;}
function field(label,name,value='',type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function formValues(form){return Object.fromEntries(new FormData(form));}
function dayEntries(){return state.entries.filter(e=>e.date===date);}
function statusBadge(value,target,hasRecords,unit='g'){
 const status=targetStatus(value,target,hasRecords);return `<span class="nutrition-badge status-${status.kind}">${status.label} · ${status.percent}%</span>${hasRecords?`<small class="nutrition-difference">${status.difference>0?'+':''}${Math.round(status.difference*10)/10} ${unit} respecto al objetivo</small>`:''}`;
}
function stats(){const t=totals(dayEntries()),targets=targetsForDay(state,date),hasRecords=dayEntries().length>0;return `<div class="grid">${[['Proteínas','p','protein'],['Hidratos','c','carbs'],['Grasas','f','fat']].map(([n,k,g])=>`<div class="card stat status-${targetStatus(t[k],targets[g],hasRecords).kind}"><span>${n}</span><strong>${Math.round(t[k])} <span>/ ${targets[g]} g</span></strong>${statusBadge(t[k],targets[g],hasRecords)}<div class="bar"><i style="width:${Math.min(100,t[k]/targets[g]*100)}%"></i></div></div>`).join('')}</div>`;}
function activityMarkup(){
 const activities=state.activities.filter(a=>a.date===date&&!a.planned),suggested=dailyWeights(state.weights).filter(w=>w.date<=date).at(-1),weight=suggested?.weight||state.profile.predictor?.input?.weight||'';
 return `<div class="card"><details id="activity-details" ${activityOpen||page==='actividad'?'open':''}><summary>Actividad del día · ${activities.length} registros</summary><form id="activity-form" class="fields" style="margin-top:20px"><label>Preset de actividad<select id="activity-preset"><option value="">Personalizada</option>${(state.activityPresets||[]).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><div><button type="button" id="save-activity-preset">Guardar como preset</button> <button type="button" id="remove-activity-preset">Eliminar preset</button></div><label>Actividad<select name="type">${['Correr','Escalada','Caminar','Fuerza','Ciclismo','Natación','Yoga','Otro'].map(n=>`<option>${n}</option>`).join('')}</select></label><label id="sport-variant-label">Modalidad / ritmo<select name="variant"></select></label>${field('Duración activa (minutos)','minutes','','number','required min="1" max="1440" step="1"')}<label id="sport-weight-label">Peso usado en la estimación (kg)<input name="exerciseWeight" type="number" min="20" max="400" step="0.01" value="${esc(weight)}"></label>${field('Pasos (opcional)','steps','','number','min="0" max="200000"')}${field('Notas','notes','','text','maxlength="300"')}<p id="exercise-preview" class="catalog-info" role="status" style="grid-column:1/-1"></p><button class="primary">Guardar actividad</button></form><p class="catalog-info">En escalada indica solo minutos de escalada activa; excluye descansos y aseguramiento. ${suggested?'Peso sugerido: registro del '+esc(suggested.date)+'.':weight?'Peso sugerido: último cálculo del perfil.':'Indica tu peso para estimar el gasto.'} Revísalo antes de guardar. El gasto es una aproximación poblacional.</p><details><summary>Método de estimación</summary><p class="catalog-info">Extra sobre reposo ≈ (MET − 1) × 3,5 × peso en kg / 200 × minutos activos. No es una medida de reloj ni una cifra exacta. Fuentes: <a href="https://pacompendium.com/running/" target="_blank" rel="noopener">Compendio 2024 · correr</a> y <a href="https://pacompendium.com/sports/" target="_blank" rel="noopener">escalada</a>. El ejercicio ya puede estar incluido en el factor de actividad del predictor: estas calorías no se suman al objetivo ni se restan a lo ingerido.</p></details></details><div class="activity-list">${activities.map(a=>`<div class="food-row"><div>${esc(a.type)} · ${a.minutes} min<small>${a.energyEstimate?esc(a.energyEstimate.label)+' · ≈ '+esc(a.energyEstimate.kcal)+' kcal extra estimadas':'Sin estimación de gasto'}${a.steps?' · '+esc(a.steps)+' pasos':''}${a.notes?' · '+esc(a.notes):''}</small></div><button data-activity-delete="${esc(a.id)}" aria-label="Eliminar actividad">×</button></div>`).join('')||'<p class="empty">Sin actividades registradas para esta fecha.</p>'}</div></div>`;
}
function adherenceMarkup(){
 const end=date>today()?today():date,days=adherenceDays(state,end,adherenceRange),closed=days.filter(d=>d.closed&&d.hasRecords),caloriesOK=closed.filter(d=>d.statuses.goal.kind==='ok').length,allOK=closed.filter(d=>Object.values(d.statuses).every(s=>s.kind==='ok')).length,review=state.dayReviews?.some(r=>r.date===date);
 return `<section class="card"><div class="section-head"><h2>Seguimiento de objetivos</h2><label>Periodo<select id="adherence-range"><option value="7" ${adherenceRange===7?'selected':''}>7 días</option><option value="28" ${adherenceRange===28?'selected':''}>28 días</option></select></label></div><details class="adherence-method"><summary>Criterios de seguimiento</summary><p class="catalog-info">Comparación orientativa: por debajo de 90 % en ámbar, entre 90 y 110 % en verde, por encima de 110 % en rojo. Durante el día indica progreso, no un resultado final. Solo los días marcados completos entran en el resumen; los días incompletos o sin registros no se consideran incumplidos.</p><p class="catalog-info">Al completar se guardan sus objetivos de referencia. Editar los alimentos recalcula la comparación; cambiar los objetivos del perfil no altera la referencia de un día ya cerrado.</p></details><p>${closed.length} días completos de ${adherenceRange} · Calorías en rango: ${closed.length?caloriesOK+'/'+closed.length:'—'} · Calorías y todos los macros en rango: ${closed.length?allOK+'/'+closed.length:'—'}</p><button id="review-day" ${date>today()||(!review&&!dayEntries().length)?'disabled':''}>${review?'Reabrir día':'Marcar día completo'}</button><details class="adherence-detail"><summary>Ver detalle diario</summary><div class="adherence-scroll"><table><thead><tr><th>Fecha</th><th>Estado</th><th>Calorías</th><th>Proteína</th><th>Hidratos</th><th>Grasas</th></tr></thead><tbody>${days.map(d=>`<tr><td>${d.date}</td><td>${d.closed?'Completo':d.hasRecords?'Sin cerrar':'Sin registros'}</td>${TARGET_KEYS.map(k=>`<td><span class="nutrition-badge status-${d.statuses[k].kind}">${d.statuses[k].label} · ${d.statuses[k].percent}%</span></td>`).join('')}</tr>`).join('')}</tbody></table></div></details></section>`;
}
function meals(){return `<div class="card"><div class="section-head"><h2>Diario de comidas</h2><span class="muted">${Math.round(totals(dayEntries()).kcal)} kcal</span></div>${['Desayuno','Comida','Cena','Tentempiés'].map(m=>{const entries=dayEntries().filter(e=>e.meal===m);return `<section class="meal"><div class="meal-head"><h3>${m} <span class="muted">· ${Math.round(totals(entries).kcal)} kcal</span></h3>${entries.length?`<button class="preset-save" data-save-preset="${m}" aria-label="Guardar ${m} como preset">Guardar preset</button>`:''}<button data-meal="${m}" aria-label="Añadir a ${m}">+</button></div>${entries.length?entries.map(e=>`<div class="food-row"><div>${esc(e.food.name)}<small>${esc(e.quantityLabel||(e.food.basis==='portion'?e.servings+' raciones':e.grams+' g'))} · ${Math.round(entryNutrients(e).kcal)} kcal</small></div><button data-delete="${e.id}" aria-label="Eliminar ${esc(e.food.name)}">×</button></div>`).join(''):'<p class="empty">Sin alimentos registrados.</p>'}${(state.plans||[]).filter(p=>p.date===date&&p.meal===m&&!state.entries.some(e=>e.planId===p.id)).map(p=>`<div class="food-row planned-row"><div><strong>Programado · ${esc(p.food.name)}</strong><small>${Math.round(entryNutrients(p).kcal)} kcal previstas · pendiente de registrar</small></div><label>${p.food.basis==='portion'?'Raciones':'Gramos'}<input data-pending-amount="${esc(p.id)}" type="number" min="0.1" max="10000" step="0.1" value="${p.food.basis==='portion'?p.servings:p.grams}" style="max-width:95px"></label><button data-log-plan="${esc(p.id)}">Registrar</button></div>`).join('')}</section>`;}).join('')}</div>`;}
function chart(){return '<div id="weight-chart"></div>';}
function render(){weightChart.unmount();page=location.hash.slice(1);if(!pages[page])page='hoy';$('main').classList.toggle('diary-view',page==='hoy');if(cloud.configured&&(!connected||syncError)){page='perfil';history.replaceState(null,'','#perfil');}$('nav').innerHTML=Object.entries(pages).map(([k,[icon,n]])=>`<a href="#${k}" aria-label="${n}" title="${n}" ${k===page?'aria-current="page"':''} class="${k===page?'active':''}"><span class="nav-icon" aria-hidden="true">${navIcon(k)}</span><span class="nav-label">${n}</span></a>`).join('');$('#title').textContent=pages[page][1];$('#day-navigation').hidden=page!=='hoy';$('#today-button').setAttribute('aria-pressed',String(date===today()));$('#diary-date').hidden=page!=='hoy';$('#diary-date').textContent=page==='hoy'?new Date(date+'T12:00:00Z').toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}):'';if(renderGate())return;if(page==='recetas'){recipeUI.render($('#content'));return;}if(page==='calendario'){plannerUI.render($('#content'),date);return;}const t=totals(dayEntries()),targets=targetsForDay(state,date),calStatus=targetStatus(t.kcal,targets.goal,dayEntries().length>0),exercise=exerciseSummary(state.activities.filter(a=>a.date===date&&!a.planned));let html='';
if(page==='hoy')html=`<section class="card hero daily-summary status-${calStatus.kind} ${[t.kcal,t.p,t.c,t.f].every(v=>v===0)?'is-empty':''}" aria-label="Resumen diario"><div class="calorie-summary"><span class="eyebrow">Calorías del día</span><div class="big">${Math.round(t.kcal)} <small>/ ${targets.goal} kcal</small></div>${statusBadge(t.kcal,targets.goal,dayEntries().length>0,'kcal')}</div>${stats()}<div class="summary-footer"><div class="hero-actions"><button id="add-main">+ Registrar comida</button><button id="add-activity">+ Registrar actividad</button></div><div class="exercise-energy"><span>Actividad extra</span><strong id="exercise-energy">≈ ${exercise.kcal} kcal</strong><small>Orientativo · no modifica el objetivo${exercise.missing?' · '+exercise.missing+' sin estimar':''}</small></div></div></section><div class="split diary-content">${meals()}<div><div class="card"><h2>Evolución del peso</h2>${chart()}<p><a href="#evolucion">Registrar peso →</a></p></div></div></div>${activityMarkup()}${adherenceMarkup()}`;
if(page==='alimentacion')html=`<p class="sub">Registro de alimentos y cantidades.</p>${stats()}${meals()}<div class="card"><h2>Biblioteca de alimentos</h2><p class="catalog-info">${foods.length} alimentos básicos orientativos y ${state.custom.length} alimentos propios. Cantidades por 100 g; comprueba etiquetas y distingue alimentos crudos y cocinados. Los básicos no constituyen todavía un catálogo certificado de USDA. La búsqueda online utiliza Open Food Facts, cuyos datos pueden estar incompletos.</p><button id="add-main" class="primary">Explorar y añadir alimentos</button></div>`;
if(page==='evolucion')html=`<p class="sub">Historial de peso y medidas corporales.</p><div class="card"><h2>Tendencia de peso</h2>${chart()}</div><div class="card"><h2>Importar historial RENPHO</h2><p class="catalog-info">Añade el CSV exportado en kg. Se conservan todas las medidas con su hora local original, sin reemplazar registros existentes. Los valores de composición corporal son estimaciones de la báscula y no modifican los objetivos automáticamente.</p><input type="file" id="renpho-file" accept=".csv,text/csv" aria-label="CSV de RENPHO"><div id="renpho-preview" role="status"></div></div><div class="card"><h2>Registrar peso y medidas</h2><p class="catalog-info">El porcentaje de grasa de una báscula es una estimación sensible a hidratación y condiciones de medida. Compara tendencias en condiciones similares. La masa libre de grasa calculada incluye agua, huesos y órganos; no equivale a masa muscular ni modifica automáticamente tus objetivos.</p><form id="weight-form" class="fields">${field('Peso (kg)','weight','','number','required min="20" max="400" step="0.1"')}${field('Grasa corporal estimada (%, opcional)','bodyFat','','number','min="3" max="65" step="0.1"')}${['Cintura','Cadera','Pecho','Brazo','Muslo'].map((n,i)=>field(n+' (cm)',['waist','hip','chest','arm','thigh'][i],'','number','min="1" max="300" step="0.1"')).join('')}<button class="primary">Guardar registro del día</button></form></div><div class="card"><h2>Historial</h2><div style="overflow:auto"><table><thead><tr><th>Fecha</th><th>Peso</th><th>Grasa estimada</th><th>Masa libre de grasa</th><th>Cintura</th><th>Cadera</th><th>Pecho</th><th>Brazo</th><th>Muslo</th><th></th></tr></thead><tbody>${[...state.weights].sort((a,b)=>b.date.localeCompare(a.date)).map(w=>`<tr><td>${esc(w.date)}${w.time?'<br><small>'+esc(w.time)+'</small>':''}${w.source==='renpho'?'<br><small>RENPHO</small>':''}</td><td>${w.weight} kg</td><td>${Number.isFinite(w.bodyFat)?w.bodyFat+' %':'—'}</td><td>${Number.isFinite(w.fatFreeMass)?w.fatFreeMass+' kg':Number.isFinite(w.bodyFat)?(w.weight*(1-w.bodyFat/100)).toFixed(1)+' kg':'—'}</td><td>${w.waist||'—'}</td><td>${w.hip||'—'}</td><td>${w.chest||'—'}</td><td>${w.arm||'—'}</td><td>${w.thigh||'—'}</td><td>${w.renphoMetrics?'<details><summary>Medidas RENPHO</summary><dl>'+Object.entries(w.renphoMetrics).filter(([,v])=>v!==null).map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl></details>':''}<button data-weight-delete="${esc(w.id||w.date)}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>${!state.weights.length?'<p class="empty">Sin registros.</p>':''}</div>`;
if(page==='actividad')html=`<p class="sub">Registro de actividad y gasto extra orientativo. Las calorías ingeridas y los objetivos no se modifican.</p>${activityMarkup()}`;
if(page==='perfil')html=`<p class="sub">Datos personales y objetivos nutricionales.</p>${predictorMarkup(state.profile,dailyWeights(state.weights).filter(w=>w.date<=today()).at(-1)?.weight)}<div id="profile-timeline">${weightTimelineMarkup(state.profile.predictor,state.profile.goal)}</div><div class="card"><h2>Datos y objetivos</h2><p class="catalog-info">Nombre, altura y sexo de la ecuación quedan de solo lectura al guardarse. Edad, registros y objetivos siguen editables.</p><p class="catalog-info">Campos vinculados: las calorías escalan todos los macros; un macro conserva las calorías y reparte el resto entre los otros dos. Pulsa Guardar perfil para confirmar.</p><form id="profile-form" class="fields">${field('Nombre','name',state.profile.name,'text','maxlength="50"')}${field('Altura (cm, opcional)','height',state.profile.height||'','number','min="80" max="250"')}${field('Edad (opcional)','age',state.profile.age||'','number','min="18" max="110"')}${field('Objetivo diario (kcal)','goal',state.profile.goal,'number','required min="800" max="10000"')}${field('Proteínas (g)','protein',state.profile.protein,'number','required min="1" max="1000" step="0.1"')}${field('Hidratos (g)','carbs',state.profile.carbs,'number','required min="1" max="2000" step="0.1"')}${field('Grasas (g)','fat',state.profile.fat,'number','required min="1" max="1000" step="0.1"')}<button class="primary">Guardar perfil</button></form><p class="catalog-info">Los objetivos iniciales son ejemplos editables, no una recomendación personalizada. Ajusta los tuyos con un profesional si lo necesitas.</p></div><div class="card"><h2>Copias de seguridad</h2><p class="sub">${cloud.configured?'Se guardan en tu base de datos privada.':'Se guardan solo en este navegador y dispositivo.'} Exporta copias con frecuencia: ${cloud.configured?'los cambios se guardan en el servidor.':'borrar los datos del navegador elimina tus registros.'} La importación reemplaza todos los datos actuales.</p><button id="export" class="primary">Exportar copia JSON</button> <button id="import">Importar copia JSON</button><input type="file" id="import-file" accept="application/json" hidden><hr><h3>Importar diario de FatSecret</h3><p class="catalog-info">Selecciona el CSV detallado de alimentos. Se añadirá al historial sin reemplazarlo. Reimportar el mismo registro no lo duplica. Las cantidades sin peso se conservan como raciones.</p><input type="file" id="fatsecret-file" accept=".csv,text/csv" aria-label="CSV detallado de FatSecret"><div id="fatsecret-preview" role="status"></div><p class="catalog-info">La búsqueda online envía el texto buscado a Open Food Facts. ${cloud.configured?'Tu perfil y tus registros se guardan en tu base de datos privada.':'Tus registros y tu perfil permanecen en el dispositivo.'}</p></div>`;
if(page==='perfil')html+=cloud.configured?'<section class="card" id="account-panel"><h2>Cuenta y almacenamiento</h2><p>Base de datos conectada · guardado remoto.</p><button id="cloud-refresh">Actualizar datos</button> <button id="logout">Cerrar sesión</button><p id="account-status" role="status"></p></section>':'<section class="card" id="account-panel"><h2>Almacenamiento</h2><p>Modo local: falta conectar la base de datos.</p></section>';
$('#content').innerHTML=html;if($('#weight-chart'))weightChart.mount($('#weight-chart'),state.weights,state.profile.predictor?.input?.objective==='lose'?state.profile.predictor.input.targetWeight:null);bind();if($('#account-status'))$('#account-status').textContent=sessionNotice;}
function openFood(m='Desayuno',destination='diary'){foodDestination=destination;foodSelection=[];$('#food-dialog h2').textContent=destination==='recipe'?'Añadir ingrediente':destination==='plan'?'Programar comida · '+planDate:'Añadir alimento';$('#meal-select').closest('label').hidden=destination==='recipe';meal=m;$('#meal-select').value=m;$('#search').value='';showResults();renderFoodSelection();renderMealPresets();$('#food-dialog').showModal();$('#search').focus();}
function catalogFoods(){return [...state.custom,...foods,...(foodDestination!=='recipe'?recipeFoods(state.recipes||[]):[])];}
function showResults(list){
 dialogFoodList=list||null;
 const query=$('#search').value.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
 const suggestions=!list&&!query&&foodDestination!=='recipe'?frequentFoods(state.entries,meal):[];
 const keys=new Set(suggestions.map(x=>foodKey(x.food)));
 results=list||[...suggestions.map(x=>({...x.food,suggestedAmount:x.amount,usageCount:x.count})),...catalogFoods().filter(f=>!keys.has(foodKey(f))&&f.name.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(query))];
 $('#results').innerHTML=(suggestions.length?`<h3>Frecuentes en ${esc(meal)} · ${suggestions.length}</h3>`:!query&&!list&&foodDestination!=='recipe'?'<p class="catalog-info">Sin historial para esta comida. Se muestra el catálogo.</p>':'')+results.slice(0,60).map((f,i)=>`<div class="result"><div><p>${esc(f.name)}</p><small>${Math.round(f.kcal)} kcal · P ${Math.round(f.p*100)/100} · HC ${Math.round(f.c*100)/100} · G ${Math.round(f.f*100)/100} / ${f.basis==='portion'?'ración de referencia':'100 g'}<br>${f.basis==='portion'?esc(f.portionLabel)+'<br>':''}${esc(f.source||'Alimento propio')}${f.usageCount?' · '+f.usageCount+' registros en '+esc(meal):''}</small></div><label>${f.basis==='portion'?'Raciones':'Gramos'}<input id="grams-${i}" type="number" min="0.1" step="0.1" max="10000" value="${f.suggestedAmount??(f.basis==='portion'?1:100)}" aria-label="Cantidad de ${esc(f.name)}"></label><button data-result="${i}" aria-label="Añadir ${esc(f.name)}">+</button></div>`).join('')||'<p class="empty">No hay resultados. Prueba online o crea tu alimento.</p>';
 $('#results').querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{const i=+b.dataset.result,input=$('#grams-'+i);if(!input.checkValidity()){input.reportValidity();return;}const {suggestedAmount,usageCount,...food}=results[i];foodSelection.push({food:structuredClone(food),amount:Number(input.value)});renderFoodSelection();});
}
async function saveMealPreset(entries,targetMeal){
 const name=prompt('Nombre de la comida guardada (preset)',targetMeal+' habitual');if(name===null)return false;
 let preset;try{preset=makeMealPreset(name,targetMeal,entries);}catch(error){if($('#food-dialog').open&&$('#selection-status'))$('#selection-status').textContent=error.message;else toast(error.message);return false;}
 const existing=(state.presets||[]).find(p=>p.meal===targetMeal&&p.name.toLocaleLowerCase()===preset.name.toLocaleLowerCase());
 if(existing){if(!confirm('Ya existe un preset con este nombre y comida. ¿Actualizar sus alimentos y cantidades?'))return false;preset.id=existing.id;}
 state.presets=[...(state.presets||[]).filter(p=>p.id!==preset.id),preset];return save();
}
function renderMealPresets(){
 const panel=$('#meal-presets'),presets=[...(state.presets||[])].sort((a,b)=>Number(b.meal===meal)-Number(a.meal===meal)||a.name.localeCompare(b.name));
 panel.hidden=!presets.length;if(!presets.length){panel.innerHTML='';return;}
 panel.innerHTML=`<h3>Comidas guardadas (presets)</h3><label>Comida guardada<select id="preset-select">${presets.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.meal)} · ${p.items.length} alimentos · ${Math.round(presetTotals(p).kcal)} kcal</option>`).join('')}</select></label><p class="catalog-info">Carga los alimentos por separado en la selección. Puedes cambiar cantidades o quitar alimentos antes de confirmar. No se añade nada al diario hasta confirmar.</p><div class="search-actions"><button id="load-meal-preset">Cargar alimentos del preset</button><button id="delete-meal-preset" class="danger">Eliminar preset</button></div><p id="preset-status" role="status"></p>`;
 $('#load-meal-preset').onclick=()=>{const preset=(state.presets||[]).find(p=>p.id===$('#preset-select').value);if(!preset)return;foodSelection.push(...presetSelection(preset));renderFoodSelection();$('#preset-status').textContent=`${preset.items.length} alimentos añadidos a la selección. Se mantienen los alimentos que ya habías seleccionado.`;};
 $('#delete-meal-preset').onclick=async()=>{const id=$('#preset-select').value;if(!confirm('¿Eliminar este preset? Los registros del diario y la selección actual se conservarán.'))return;state.presets=(state.presets||[]).filter(p=>p.id!==id);if(!await save())return;renderMealPresets();};
}
function renderFoodSelection(){
 $('#food-selection').innerHTML=`<h3>Selección · ${foodSelection.length} alimentos</h3>${foodSelection.length?`<div class="selection-items">${foodSelection.map((item,i)=>`<div class="food-row"><span>${esc(item.food.name)}</span><label>${item.food.basis==='portion'?'Raciones':'Gramos'}<input data-selection-amount="${i}" type="number" min="0.1" step="0.1" max="10000" value="${item.amount}" style="width:90px"></label><button data-remove-selection="${i}" aria-label="Quitar selección ${i+1}">×</button></div>`).join('')}</div>`:'<p class="empty">Añade alimentos con el botón +. Puedes seguir buscando sin cerrar esta ventana.</p>'}<p>${foodDestination==='recipe'?'Se añadirán al borrador de la receta.':`${foodDestination==='plan'?'Planificación · '+esc(planDate):'Diario · '+date} · ${esc(meal)}`}</p><p id="selection-status" role="alert"></p><button id="confirm-foods" class="primary" ${foodSelection.length?'':'disabled'}>Confirmar selección</button>${foodSelection.length?'<button id="save-selection-preset" type="button">Guardar selección como preset</button>':''}`;
 $('#food-selection').querySelectorAll('[data-remove-selection]').forEach(b=>b.onclick=()=>{foodSelection.splice(Number(b.dataset.removeSelection),1);renderFoodSelection();});
 $('#food-selection').querySelectorAll('[data-selection-amount]').forEach(input=>input.oninput=()=>{foodSelection[Number(input.dataset.selectionAmount)].amount=Number(input.value);});
 if($('#save-selection-preset'))$('#save-selection-preset').onclick=async()=>{
  for(const input of $('#food-selection').querySelectorAll('input'))if(!input.checkValidity()){input.reportValidity();return;}
  const entries=foodSelection.map(i=>withAmount({food:i.food},i.amount));if(!await saveMealPreset(entries,meal))return;renderMealPresets();$('#preset-status').textContent='Preset guardado. Los alimentos siguen en la selección; todavía no se han registrado.';
 };
 $('#confirm-foods').onclick=async()=>{
  if(!foodSelection.length)return;
  for(const input of $('#food-selection').querySelectorAll('input'))if(!input.checkValidity()){input.reportValidity();return;}
  $('#confirm-foods').disabled=true;
  if(foodDestination==='recipe'){for(const item of foodSelection)recipeUI.addIngredient(item.food,item.amount);}
  else{
   const entries=foodSelection.map(item=>withAmount({id:crypto.randomUUID(),date:foodDestination==='plan'?planDate:date,meal,food:structuredClone(item.food)},item.amount));
   if(foodDestination==='plan')state.plans=[...(state.plans||[]),...entries];else state.entries.push(...entries);
   if(!await save())return;
  }
  foodSelection=[];$('#food-dialog').close();render();toast(foodDestination==='recipe'?'Ingredientes añadidos al borrador':foodDestination==='plan'?'Comidas programadas':'Alimentos registrados');
 };
}
