 try{prediction=predictTargets({...v,weight:Number(v.weight),height:Number(v.height),age:Number(v.age),...(fixed.height!==null?{height:fixed.height}:{}),...(fixed.sex!==null?{sex:fixed.sex}:{}),excluded:!!v.excluded});}
 catch(error){$('#prediction').textContent=error.message;return;}
