 $('#remove-activity-preset').onclick=async()=>{const id=$('#activity-preset').value;if(!id)return toast('Selecciona un preset.');if(!confirm('¿Eliminar este preset de actividad? Los registros existentes se conservan.'))return;state.activityPresets=(state.activityPresets||[]).filter(p=>p.id!==id);if(await save())render();};
